"use strict";(self.webpackChunkuxcam=self.webpackChunkuxcam||[]).push([[7910],{67785:function(e,a,t){t.r(a),t.d(a,{Head:function(){return o},default:function(){return c}});var s=t(96540),r=t(86997),n=t(54727);var i={seo:{title:"Case study | PlaceMakers | UXCam",description:"Discover how New Zealand based construction material company doubled their sales after using UXCam",image:"https://images.ctfassets.net/vv1yxl437u7d/3Mn0AbpUmb4aFxUXNgpzY6/77b23638bee2a4c3cc29e6336ace2e1f/metaimageNEW.png"},hero:{industry:"Construction",title:"How PlaceMakers <span>Doubled Sales After Using UXCam</span>",description:"PlaceMakers is a construction material supplier in New Zealand with more than 60 stores across the country. They launched their app in April 2020 and have since grown to more than 3,000 daily users and 100,000 monthly sessions.",featuresUsed:[{label:"Session Replay",url:"/experience-analytics/session-replay"},{label:"Heatmaps",url:"/experience-analytics/heatmaps"},{label:"Event Analytics",url:"/product-analytics/smart-events"}],image:"https://images.ctfassets.net/vv1yxl437u7d/7JGZAsH0wpXR35E2NUya9x/c5d3df70e4e9eecc8e163b9072d1bff9/IMG_Company_profile___PlaceMakers.png",vimeoId:"844182714?h=15f47d3718"},stats:[{value:"2,100+",label:"employees in New Zealand"},{value:"Sales doubled",label:"since implementing UXCam"},{value:"Research time",label:"reduced from months to days"}],challenge:{title:"The Challenge",backgroundImage:"https://images.ctfassets.net/vv1yxl437u7d/1Ov4GcUZwhwz6Gdk7x9TIS/ad9823ae58f2e2026f64d865f820a987/Vector.svg",paragraphs:["The PlaceMakers app launched a month after lockdowns began in New Zealand in 2020. A surge in demand combined with pandemic supply chain disruptions meant materials were selling out faster than the app could update stock levels.","Customers were able to add a product to their basket, but by the time they got to checkout, the item was displayed as unavailable.","To solve this, the team built a feature called Constrained Products, a tag on materials under a certain stock level that clearly showed they weren't available to order. But sales dropped by 80% after its release."],quote:{text:"When we added [Constrained Products] we didn't pay much attention to the UX side of the message and what we saw is that orders from April [compared to March] were down 80%.",author:"Blake Johnson",role:"Product Owner",image:"https://images.ctfassets.net/vv1yxl437u7d/1ikWoCKcb3Zsyw3iNUU4Dp/d6ca482a30a2760320063066ece5b077/blakethumb.png"}},solution:{title:"The Solution",backgroundImage:"https://images.ctfassets.net/vv1yxl437u7d/28xui9UzDyaFzt7EfaJuio/74b1070ae5cc420b5ac71c1dee040858/Vector.svg",paragraphs:['After watching just a few <a href="/experience-analytics/session-replay">session replays</a> and <a href="/experience-analytics/heatmaps">heatmaps</a>, the team discovered that their messaging was too strong. With red and bold lettering communicating the product wasn\'t available to order, users stopped purchasing in advance for future deliveries.',"Users were scrolling past materials with the Constrained Products tag, even though it perfectly matched their search intent and would be back in stock shortly.","The team revamped the design with a more positive approach, communicating to users that the product is available but delivery may take slightly longer."],quote:{text:"UXCam's Session Replay feature clearly showed that users were scrolling past materials with the Constrained Products tag, even though it perfectly matched their search intent and would be back in stock shortly.",author:"Blake Johnson",role:"Product Owner",image:"https://images.ctfassets.net/vv1yxl437u7d/1ikWoCKcb3Zsyw3iNUU4Dp/d6ca482a30a2760320063066ece5b077/blakethumb.png"}},whatsNext:{title:"The Result",backgroundImage:"https://images.ctfassets.net/vv1yxl437u7d/Bc9n79vDsJLoV0HUy6g4j/db1b14e3e0162ced77ac4f4e7f6b5e6a/Path-7.svg",paragraphs:["Once the revamped design was implemented, the team checked back with UXCam and saw clear results:<ul><li>Sales hadn't just recovered, they had doubled</li><li>The entire process from identifying the issue to testing the solution took just 3 days</li><li>Research time reduced from months to days</li></ul>","PlaceMakers continuously uses UXCam insights to make better-informed decisions on UX design and new feature releases."],quote:{text:"UXCam helped us to find a hidden flaw with one of our new features. Within three days, we ran an experiment with a revamped design. The updates helped us double our sales after the release.",author:"Blake Johnson",role:"Product Owner",image:"https://images.ctfassets.net/vv1yxl437u7d/1ikWoCKcb3Zsyw3iNUU4Dp/d6ca482a30a2760320063066ece5b077/blakethumb.png"}}},l=t(17437);const o=()=>(0,l.Y)(s.Fragment,null,(0,l.Y)(n.A,{title:i.seo.title,description:i.seo.description,image:{file:{url:i.seo.image}}}),(0,l.Y)("link",{rel:"canonical",href:"https://uxcam.com/case-study/placemakers/"}),(0,l.Y)("link",{rel:"alternate",hrefLang:"en",href:"https://uxcam.com/case-study/placemakers/"}),(0,l.Y)("link",{rel:"alternate",hrefLang:"es",href:"https://uxcam.com/es/case-study/placemakers/"}),(0,l.Y)("link",{rel:"alternate",hrefLang:"pt-BR",href:"https://uxcam.com/br/case-study/placemakers/"}),(0,l.Y)("link",{rel:"alternate",hrefLang:"x-default",href:"https://uxcam.com/case-study/placemakers/"}));var c=()=>(0,l.Y)(r.A,{data:i})}}]);